package completion

import (
	_ "embed"
	"sync"
)

// builtinData is the pinned Carapace snapshot generated by
// tools/completiongen. It is plain data: nothing from the source it came from
// is ever executed.
//
//go:embed data/catalog.bin
var builtinData []byte

var (
	builtinOnce    sync.Once
	builtinCatalog *Catalog
	builtinErr     error
)

// Builtin returns the catalog embedded in the binary. Decoding happens once,
// on first use, so callers do it on a background goroutine rather than while
// painting.
func Builtin() (*Catalog, error) {
	builtinOnce.Do(func() {
		builtinCatalog, builtinErr = Decode(builtinData)
	})
	return builtinCatalog, builtinErr
}

// BuiltinBytes exposes the embedded snapshot for tests and cache comparisons.
// Callers must not modify the returned slice.
func BuiltinBytes() []byte { return builtinData }
